class Solution {
  public int[] validSequence(String word1, String word2) {
    int n = word1.length(), m = word2.length();
    // suffixMatched[i]: longest suffix of word2 that is a subsequence of word1[i..]
    int[] suffixMatched = new int[n + 1];
    for (int i = n - 1; i >= 0; i--) {
      suffixMatched[i] = suffixMatched[i + 1];
      if (suffixMatched[i] < m && word1.charAt(i) == word2.charAt(m - 1 - suffixMatched[i]))
        suffixMatched[i]++;
    }
    int[] ans = new int[m];
    int j = 0;
    boolean usedChange = false;
    for (int i = 0; i < n && j < m; i++) {
      if (word1.charAt(i) == word2.charAt(j)) {
        ans[j++] = i;
      } else if (!usedChange && suffixMatched[i + 1] >= m - j - 1) {
        // spend the single change here: the rest must then match exactly
        usedChange = true;
        ans[j++] = i;
      }
    }
    return j == m ? ans : new int[0];
  }
}
